"use client";

import { useRouter, useParams } from "next/navigation";
import { useQuery, useMutation } from "@tanstack/react-query";
import axios from "axios";
import { Formik, Form, Field, ErrorMessage } from "formik";
import * as Yup from "yup";
import { toast } from "react-toastify";

const fetchProduct = async (productId: string) => {
  const response = await axios.get(`/api/products/${productId}`);
  return response.data;
};

const updateProduct = async ({ productId, values }: { productId: string; values: any }) => {
  const response = await axios.patch(`/api/products/update/${productId}`, values);
  return response.data;
};

const EditDraftProduct = () => {
  const router = useRouter();
  const { productId } = useParams() as { productId: string };

  const { data: product, isLoading } = useQuery({
    queryKey: ["product", productId],
    queryFn: () => fetchProduct(productId),
    enabled: !!productId,
  });

  const mutation = useMutation({
    mutationFn: (values: any) => updateProduct({ productId, values }),
    onSuccess: () => {
      toast.success("Product updated successfully!");
    },
    onError: (error) => {
      toast.error("Failed to update product.");
      console.error(error);
    },
  });

  if (isLoading) return <div>Loading...</div>;

  return (
    <div className="p-6 bg-white shadow-md rounded-lg">
      <h2 className="text-3xl font-semibold mb-4">Edit Product Draft</h2>
      <Formik
        initialValues={{
          name: product.name || "",
          category: product.category || "",
          price: product.price || 0,
        }}
        validationSchema={Yup.object({
          name: Yup.string().required("Required"),
          category: Yup.string().required("Required"),
          price: Yup.number().min(0, "Must be a positive number").required("Required"),
        })}
        onSubmit={(values) => mutation.mutate(values)}
      >
        {({ isSubmitting }) => (
          <Form className="space-y-4">
            <div>
              <label className="block">Name</label>
              <Field type="text" name="name" className="border p-2 rounded w-full" />
              <ErrorMessage name="name" component="div" className="text-red-500" />
            </div>

            <div>
              <label className="block">Category</label>
              <Field type="text" name="category" className="border p-2 rounded w-full" />
              <ErrorMessage name="category" component="div" className="text-red-500" />
            </div>

            <div>
              <label className="block">Price</label>
              <Field type="number" name="price" className="border p-2 rounded w-full" />
              <ErrorMessage name="price" component="div" className="text-red-500" />
            </div>

            <button
              type="submit"
              className="bg-blue-500 text-white px-4 py-2 rounded"
              disabled={isSubmitting || mutation.isLoading}
            >
              {mutation.isLoading ? "Updating..." : "Update Product"}
            </button>
          </Form>
        )}
      </Formik>
    </div>
  );
};

export default EditDraftProduct;